}

class Solution {
  public int countPrimes(int n) {
    boolean[] isPrim = new boolean[n];
    Arrays.fill(isPrim, true);
    for (int i = 2; i * i < n; i++)
      if (isPrim[i])
        for (int j = i * i; j < n; j += i)
          isPrim[j] = false;

    int count = 0;
    for (int i = 2; i < n; i++)
      if (isPrim[i]) count++;
    return count;
  }
}

class Solution:
    def countPrimes(self, n: int) -> int:
        if n < 2:
            return 0
        is_prim = [True] * n
        for i in range(2, int(n ** 0.5) + 1):
            if is_prim[i]:
                for j in range(i * i, n, i):
                    is_prim[j] = False
        return sum(1 for i in range(2, n) if is_prim[i])

impl Solution {
  pub fn count_primes(n: i32) -> i32 {
    if n < 2 {
      return 0;
    }
    let n = n as usize;
    let mut is_prim = vec![true; n];
    let mut i = 2;
    while i * i < n {
      if is_prim[i] {
        let mut j = i * i;
        while j < n {
          is_prim[j] = false;
          j += i;
        }
      }
      i += 1;
    }
    (2..n).filter(|&i| is_prim[i]).count() as i32
  }
}

const countPrimes = (n: number): number => {
  if (n < 2) return 0;
  const isPrim: boolean[] = new Array(n).fill(true);
  for (let i = 2; i * i < n; i++) {
    if (isPrim[i]) {
      for (let j = i * i; j < n; j += i) isPrim[j] = false;
    }
  }
  let count = 0;
  for (let i = 2; i < n; i++) if (isPrim[i]) count++;
